with open("start_tight.xyz","w") as f:
    f.write(f"{len(atoms2)}\ntight\n")
    for s,p in zip(atoms2,coords2): f.write(f"{s} {p[0]:.4f} {p[1]:.4f} {p[2]:.4f}\n")
